  powerW: 1.15e6,
  brakeAccel: 13,
  vMax: 103, // 370 km/h
  mainThrust: 36000, // 4 rear diffuser nozzles
  liftThrust: 68000, // 4 corner nozzles under the floor: ~3.1 G landing burn ("3.3 G at ~6.5 m")
  sideThrust: 2000, // 2 side nozzles (attitude) -> 10 nozzles, 106 kN total ("over 80 kN")
