  px: ['auto', 0.75, 1, 1.5, 2],
  draw: ['near', 'mid', 'far'],
  sens: [0.4, 0.6, 0.8, 1, 1.25, 1.5, 2, 2.5],
  invert: [false, true],
  subtitles: [true, false],
