// (out past the beach's face, over the water: citySea.js)
const QUAY = {
  x0: -OUTER - 11,
  x1: -(PROMENADE - 0.3),
  z0: ROADS[14] - 10,
  z1: WALL - 6
}
const GAUGE = 16 // m between a crane's water-side and land-side legs
const SPAN = 17 // and between its legs along the quay
const CRANES = []
const SHIP = {
  x0: -OUTER - 48,
  x1: -OUTER - 16,
  z0: QUAY.z0 + 30,
  z1: QUAY.z1 - 40,
  deck: 9
}
