  wall(-w / 2 - W, w / 2 + W, -W, 0)
  wall(-w / 2 - W, w / 2 + W, d, d + W)
  wall(-w / 2 - W, -w / 2, 0, d)
  wall(w / 2, w / 2 + W, 0, d)
